// @ts-check
/**
 * Astro config for the Stackific OS website.
 * Regular Astro pages in src/pages serve the marketing site at /; Starlight serves the docs at /docs
 * (see src/content.config.ts for how the /docs prefix is produced). https://starlight.astro.build
 */
import { defineConfig, sharpImageService } from 'astro/config';
import starlight from '@astrojs/starlight';
import starlightImageZoom from 'starlight-image-zoom';
import starlightLlmsTxt from 'starlight-llms-txt';

// https://astro.build/config
export default defineConfig({
  // Production URL: needed for the sitemap (generated by Starlight's bundled @astrojs/sitemap).
  site: 'https://os.stackific.com',
  // astro:assets re-encodes every Markdown image to WebP; these match `just site screenshot`'s lossy
  // settings (site/screenshots/process.ts), so screenshot text keeps its edges.
  image: { service: sharpImageService({ webp: { quality: 80, effort: 6, smartSubsample: true } }) },
  integrations: [
    starlight({
      title: 'Stackific OS',
      // English only: no locales.
      plugins: [
        // Generates /llms.txt, /llms-full.txt and /llms-small.txt for LLMs.
        // Per-page Markdown comes from src/pages/[...slug].md.ts.
        starlightLlmsTxt(),
        // Docs images (prompt-trail screenshots) open full size in a dialog on click, alt text as the caption.
        // Astro's built-in astro:assets already resizes them and serves WebP, since entries reference them relatively.
        starlightImageZoom(),
      ],
      // Loaded after Starlight's defaults so these overrides win.
      customCss: ['./src/styles/starlight.css'],
      components: {
        // Header title links to the docs home (/docs/), not the marketing root.
        SiteTitle: './src/components/starlight/SiteTitle.astro',
        // Adds a "Copy as Markdown" button under each docs page title.
        PageTitle: './src/components/starlight/PageTitle.astro',
        // Theme always follows the system: no picker, and stored choices are ignored.
        ThemeProvider: './src/components/starlight/ThemeProvider.astro',
        // Replaces the theme picker with a home icon (link to /).
        ThemeSelect: './src/components/starlight/ThemeSelect.astro',
        // English only, so the language selector's slot holds a GitHub link to the repository instead.
        LanguageSelect: './src/components/starlight/LanguageSelect.astro',
        // Adds Red Hat's trademark line under every docs page, as Fedora's trademark guidelines ask.
        Footer: './src/components/starlight/Footer.astro',
      },
      // Relabels the prompt trail's per-base groups (src/routeData.ts).
      routeMiddleware: './src/routeData.ts',
      // Group headings are set here; the pages inside each group are generated from its folder.
      // New pages need no config: add a file to the folder. A page's frontmatter sets its nav
      // entry (`sidebar.label`, `sidebar.order`); without `order`, pages sort by filename.
      // Unlike slugs, `directory` is a file path relative to src/content/docs: no `docs/` prefix.
      sidebar: [
        // Top-level entry, shown above every group.
        { label: 'Welcome to Stackific OS', slug: 'docs' },
        {
          label: 'User Guide',
          items: [{ autogenerate: { directory: 'user' } }],
        },
        {
          // Entries for tasks on both bases sit at the top; arch/ and fedora/ hold single-base ones.
          label: 'Prompt Trail',
          items: [{ autogenerate: { directory: 'prompt-trail' } }],
        },
      ],
    }),
  ],
});
